mapper.select:
select * from TBL_REPORT where 1=1

	and type= #{queryParam.type}


	and orgid= #{queryParam.orgid}


	and reportname like concat(concat('%',#{queryParam.reportname}),'%')


	and reporttype like concat(concat('%',#{queryParam.reporttype}),'%')


	and reporttime >=#{queryParam.startDate}


	and reporttime <=#{queryParam.endDate}



	and reporttime >=#{queryParam.startDateYear}


	and reporttime <=#{queryParam.endDateYear}



	${sql}

order by REPORTID DESC
